<?php
require_once __DIR__.'/../includes/functions.php'; require_owner();
$configs=[
 'barang'=>['title'=>'Data Barang','table'=>'barang','fields'=>['nama_barang'=>'Nama Barang','harga'=>'Harga','stok'=>'Stok'],'types'=>['nama_barang'=>'text','harga'=>'number','stok'=>'number']],
 'supplier'=>['title'=>'Data Supplier','table'=>'supplier','fields'=>['nama_supplier'=>'Nama Supplier','telepon'=>'Telepon','alamat'=>'Alamat'],'types'=>['nama_supplier'=>'text','telepon'=>'text','alamat'=>'text']],
 'pelanggan'=>['title'=>'Data Pelanggan','table'=>'pelanggan','fields'=>['nama_pelanggan'=>'Nama Pelanggan','telepon'=>'Telepon','alamat'=>'Alamat'],'types'=>['nama_pelanggan'=>'text','telepon'=>'text','alamat'=>'text']],
 'user'=>['title'=>'Data User','table'=>'users','fields'=>['nama'=>'Nama','username'=>'Username','password'=>'Password','level'=>'Level'],'types'=>['nama'=>'text','username'=>'text','password'=>'password','level'=>'select']]
];
$key=$_GET['jenis']??''; if(!isset($configs[$key])) exit('Jenis data tidak tersedia.'); $c=$configs[$key]; $table=$c['table']; $msg=''; $edit=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);
 if($action==='delete'){if($key==='user' && $id===(int)$_SESSION['user_id']){$msg='Akun yang sedang digunakan tidak dapat dihapus.';}else{$st=$pdo->prepare("DELETE FROM `$table` WHERE id=?");$st->execute([$id]);header("Location: $key.php?deleted=1");exit;}}
 if($action==='save'){$data=[];foreach($c['fields'] as $f=>$label){$data[$f]=trim($_POST[$f]??'');} if($key==='user' && $id>0 && $data['password']===''){unset($data['password']);} if($key==='user' && isset($data['password']))$data['password']=password_hash($data['password'],PASSWORD_DEFAULT); if($key==='user')$data['level']=(int)$data['level'];
 if($id>0){$sets=[];foreach(array_keys($data) as $f)$sets[]="`$f`=?";$vals=array_values($data);$vals[]=$id;$st=$pdo->prepare("UPDATE `$table` SET ".implode(',',$sets)." WHERE id=?");$st->execute($vals);}else{$cols=array_keys($data);$quoted=array_map(fn($x)=>"`$x`",$cols);$marks=array_fill(0,count($cols),'?');$st=$pdo->prepare("INSERT INTO `$table` (".implode(',',$quoted).") VALUES (".implode(',',$marks).")");$st->execute(array_values($data));}header("Location: $key.php?saved=1");exit;}}
if(isset($_GET['edit'])){$st=$pdo->prepare("SELECT * FROM `$table` WHERE id=?");$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}
$rows=$pdo->query("SELECT * FROM `$table` ORDER BY id DESC")->fetchAll();$page_title=$c['title'];require __DIR__.'/../includes/header.php';
?>
<div class="card"><h2><?= e($c['title']) ?></h2><?php if(isset($_GET['saved'])):?><div class="alert success">Data berhasil disimpan.</div><?php endif;?><?php if(isset($_GET['deleted'])):?><div class="alert success">Data berhasil dihapus.</div><?php endif;?><?php if($msg):?><div class="alert"><?=e($msg)?></div><?php endif;?>
<h3><?= $edit?'Ubah Data':'Tambah Data' ?></h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>">
<?php foreach($c['fields'] as $f=>$label):?><label><?=e($label)?></label><?php if($f==='level'):?><select name="level"><option value="1" <?=isset($edit['level'])&&(int)$edit['level']===1?'selected':''?>>1 - Owner</option><option value="2" <?=isset($edit['level'])&&(int)$edit['level']===2?'selected':''?>>2 - Kasir</option></select><?php else:?><input type="<?=e($c['types'][$f])?>" name="<?=e($f)?>" value="<?= $f==='password'?'':e($edit[$f]??'') ?>" <?=($f==='password'&&$edit)?'placeholder="Kosongkan jika tidak ingin mengubah password"':''?> <?=($f!=='password'||!$edit)?'required':''?> <?=in_array($f,['harga','stok'])?'min="0"':''?>><?php endif;?><?php endforeach;?><button type="submit">Simpan</button> <?php if($edit):?><a class="btn secondary" href="<?=e($key)?>.php">Batal</a><?php endif;?></form></div>
<div class="card"><h3>Daftar Data</h3><div class="table-wrap"><table><thead><tr><th>ID</th><?php foreach($c['fields'] as $label):?><th><?=e($label)?></th><?php endforeach;?><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['id'])?></td><?php foreach($c['fields'] as $f=>$label):?><td><?php if($f==='password'):?>••••••<?php elseif($f==='level'):?><?= (int)$r[$f]===1?'Owner':'Kasir' ?><?php else:?><?=e($r[$f])?><?php endif;?></td><?php endforeach;?><td><div class="actions"><a class="btn secondary" href="<?=e($key)?>.php?edit=<?=$r['id']?>">Edit</a><form method="post" onsubmit="return confirm('Hapus data ini?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="danger" type="submit">Hapus</button></form></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="<?=count($c['fields'])+2?>">Belum ada data.</td></tr><?php endif;?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
